function corporateView(s){const portfolio=[];for(const actor of ['player','fund','bank'])for(const c of s.companies){let q=c.shares[actor]||0,p=s.portfolio[actor][c.id];if(q||p?.realized)portfolio.push({actor,company:c.id,name:account(s,c.id).name,qty:q,cost:p?.cost||0,value:q*c.price,realized:p?.realized||0,reserved:reservedShares(s,actor,c.id),openingEstimate:p?.openingEstimate||false});}const staff=s.staff.filter(t=>t.active).map(t=>({...t,name:account(s,t.person).name}));return {owned:[...controlSet(s)].filter(id=>idx(s).companies.has(id)),offers:s.corporate.offers.slice(-30).map(o=>({...o,buyerName:account(s,o.buyer).name,targetName:account(s,o.target).name})),alliances:s.corporate.alliances.filter(a=>a.expires>s.day).map(a=>({...a,aName:account(s,a.a).name,bName:account(s,a.b).name})),news:s.corporate.campaigns.slice(-30).reverse().map(n=>({...n,actorName:account(s,n.actor).name,targetName:account(s,n.target).name,canSue:n.evidence&&managed(s,n.target)&&!s.corporate.cases.some(c=>c.news===n.id)})),cases:s.corporate.cases.slice(-30).map(c=>({...c,claimantName:account(s,c.claimant).name,defendantName:account(s,c.defendant).name})),history:s.corporate.history.slice(0,10),portfolio,orders:s.orders.slice(-40),staff,candidates:s.citizens.filter(p=>p.alive&&p.resident&&!p.employer&&p.age>=18*365&&p.age<65*365).slice(0,12).map(p=>({id:p.id,name:account(s,p.id).name,skill:p.skill})),fundProspects:s.investors.filter(id=>idx(s).people.get(id)?.alive).slice(0,12).map(id=>({id,name:account(s,id).name,max:Math.floor(Math.min(account(s,id).cash*.05,nav(s)*.5+money(250000)))})),fundOffers:s.fund.offers.filter(o=>['pending','review'].includes(o.status)).map(o=>({...o,name:account(s,o.person).name})),fundWithdrawals:s.fund.pending.map(r=>({...r,name:account(s,r.id).name})),fundPolicy:s.fund.policy,escrowPlayer:escrowCash(s,'player'),escrowFund:escrowCash(s,'fund')};}


