function marketQuote(s,cid,actor,side,qty){const c=idx(s).companies.get(cid);if(!c||c.status!=='active'||!['player','fund','bank','nf0','nf1'].includes(actor)||!['buy','sell'].includes(side)||!Number.isInteger(qty)||qty<1||qty>1000000)throw Error('Проверьте компанию и количество (1–1 000 000)');if(managed(s,actor)&&s.market?.cases.some(k=>k.status==='penalty'&&k.freezeUntil>s.day))throw Error('Комиссия временно ограничила новые биржевые сделки управляющего');const confidence=(s.market?.confidence||80)/100,depth=Math.max(500,Math.floor(c.supply*.05*(.25+confidence)*(1-(c.panic||0)*.5))),impact=Math.min(.35,qty/depth*.035);const price=Math.max(1,Math.round(c.price*(side==='buy'?1+.015+impact*.5:1-.015-impact*.5)));let left=qty,fills=[];const candidates=side==='buy'?Object.keys(c.shares):s.investors;for(const id of candidates){if(id===actor||managed(s,id))continue;const p=idx(s).people.get(id);if(!p?.alive&&!(side==='buy'&&(id==='treasury'||s.npcFunds.some(f=>f.id===id))))continue;let available=side==='buy'?(c.shares[id]||0):Math.floor(Math.min(account(s,id).cash*.025*confidence,money(2000000)*confidence)/price);let q=Math.min(left,available);if(q){fills.push({id,qty:q});left-=q;}if(!left)break;}return {price,lastPrice:Math.max(1,Math.round(c.price*(side==='buy'?1+impact:1-impact))),depth,impact,fills,available:qty-left,total:(qty-left)*price};}
