 let cap=s.companies.reduce((n,c)=>n+c.price*c.supply,0);m.index=cap/Math.max(1,m.baseCap)*100;const drawdown=clamp(1-m.index/100,0,1);m.crisis=clamp(drawdown*1.8+s.metrics.unemployment*.3+s.shock*.4,0,1);m.confidence=clamp(m.confidence*.92+(85-m.crisis*65)*.08,10,95);m.fundPeak=Math.max(m.fundPeak,nav(s));
 for(const c of s.companies){c.panic=Math.max(0,(c.panic||0)-.018);c.peakPrice=Math.max(c.peakPrice||c.price,c.price);c.creditOffer=clamp(s.policy.rate+4+m.crisis*8+(1-c.price/Math.max(1,c.peakPrice))*5+c.stress*.15,1,50);}
