 // Panicked NPC sales settle against other residents' finite cash.
 for(const c of s.companies.filter(c=>c.status==='active'&&c.panic>.12)){const seller=Object.keys(c.shares).find(id=>idx(s).people.get(id)?.alive&&(c.shares[id]||0)>10),buyer=s.investors.find(id=>id!==seller&&idx(s).people.get(id)?.alive&&account(s,id).cash>c.price*100);if(!seller||!buyer)continue;const qty=Math.min(c.shares[seller],Math.max(1,Math.floor(c.supply*c.panic*.001)),Math.floor(account(s,buyer).cash*.001/Math.max(1,c.price)));if(qty){let price=Math.max(1,Math.floor(c.price*.995));transfer(s,buyer,seller,qty*price,'Продажа NPC на фоне тревоги');c.shares[seller]-=qty;c.shares[buyer]=(c.shares[buyer]||0)+qty;c.price=price;observeCandle(s,c,price,qty);idx(s).control=null;}}
 for(const k of m.cases){if(k.status==='review'&&s.day>=k.due){const trade=k.tradeRecord||m.tape.find(t=>t.id===k.trade);const evidence=s.corporate.campaigns.find(n=>n.kind==='smear'&&n.evidence&&n.target===k.company&&n.beneficiary==='player'&&trade?.beneficiary==='player'&&Math.abs(n.day-trade.day)<=14);if(evidence){k.fine=Math.max(money(5000),Math.min(Math.floor(trade.value*.08),evidence.budget*2));k.balance=k.fine;k.status='penalty';k.freezeUntil=s.day+7;k.evidence=evidence.id;press(s,'wire','Комиссия установила связь сделок и ложной публикации','Дело '+k.id+': доказательство '+evidence.id+', связанная сделка '+k.trade+'. Штраф управляющему '+fmt(k.fine)+', ограничение новых биржевых сделок на 7 дней. Обычная крупная продажа без таких доказательств не является нарушением.',k.company);}else{k.status='closed';press(s,'wire','Проверка крупной сделки завершена без санкций','В деле '+k.id+' не обнаружено подтверждённой связи с ложной публикацией. Объём продажи сам по себе не доказывает манипуляцию.',k.company);}}
 if(k.status==='penalty'&&k.balance){const n=pay(s,'player','treasury',k.balance,'Штраф комиссии по '+k.id);k.balance-=n;}}
 for(const l of m.loans){if(!l.principal&&!l.interest)continue;const interest=Math.round(l.principal*l.rate/100/365);l.interest+=interest;const c=idx(s).companies.get(l.borrower);if(c)c.pendingExpense+=interest;if(s.day>=l.due){let n=pay(s,l.borrower,'treasury',l.principal+l.interest,'Возврат государственной поддержки'),i=Math.min(n,l.interest);l.interest-=i;l.principal-=n-i;l.overdue=l.principal+l.interest>0;}}
 if(s.day%30===0){for(const pub of ['media','wire','scope'])for(const id of s.investors.slice(0,40))if(idx(s).people.get(id)?.alive)pay(s,id,pub,money(10),'Подписка на деловую прессу');press(s,'wire','Экономика за месяц: индекс '+m.index.toFixed(1)+', безработица '+(s.metrics.unemployment*100).toFixed(1)+'%','Рынок завершает месяц у отметки '+m.index.toFixed(1)+' пункта против 100 на старте наблюдений. Без работы остаются '+(s.metrics.unemployment*100).toFixed(1)+'% жителей, а ключевая ставка составляет '+s.policy.rate+'%. '+(m.crisis>.2?'Слабый спрос и ухудшение финансирования усиливают друг друга.':'Общая устойчивость не исключает проблем отдельных компаний.')+' Следующий месяц покажет, перерастёт ли движение на бирже в изменения спроса и занятости.');const c=s.companies.filter(c=>c.status==='active').sort((a,b)=>a.lastProfit-b.lastProfit)[0];if(c)press(s,'scope','Что происходит внутри '+account(s,c.id).name,'В последнем отчёте '+account(s,c.id).name+' показала '+(c.lastProfit<0?'убыток ':'прибыль ')+fmt(Math.abs(c.lastProfit))+' за день. На счетах остаётся '+fmt(account(s,c.id).cash)+', при этом обязательства составляют '+fmt(debt(s,c.id))+'. Новый кредит обойдётся примерно в '+c.creditOffer.toFixed(1)+'% годовых. '+(c.lastProfit<0?'Убыток сокращает запас времени до нового финансирования; рост цены продукции может ухудшить спрос.':'Положительная прибыль не исключает кассового разрыва при погашении долгов.'),c.id);}
