function issuerStatement(s,p){const c=checkActor(s,p.actor);if(!c)throw Error('Выберите подконтрольную компанию');amount(p.budget);if(p.budget<money(1000)||p.budget>money(100000))throw Error('Бюджет заявления: 1 000–100 000');corporateExpense(s,c.id,p.budget,'media','Публикация отчёта компании');press(s,'media',account(s,c.id).name+': заявление эмитента','По данным самой компании: деньги '+fmt(account(s,c.id).cash)+', долг '+fmt(debt(s,c.id))+', результат дня '+fmt(c.lastProfit)+', работников '+c.workers+'. Руководство заявляет, что оценивает финансирование и производственный план. Это позиция эмитента, а не независимая оценка.',c.id,'issuer');}
