 if(c.assets===0&&c.stock===0&&debt(s,c.id)===0&&account(s,c.id).cash>0){const budget=account(s,c.id).cash,owners=Object.entries(c.shares).filter(([,q])=>q>0);for(let i=0;i<owners.length;i++){const [id,q]=owners[i];transfer(s,c.id,id,i===owners.length-1?account(s,c.id).cash:Math.floor(budget*q/c.supply),'Остаток имущества акционерам');}}
